/**
 * Opt-in large, single-transaction growth campaign. Each invocation writes exactly 200 million distinct statements,
 * using the ordinary repository transaction, default indexes, default growth policy, and default model overflow. There
 * are six requested isolation levels and five native LMDB levels: READ_UNCOMMITTED is upgraded to READ_COMMITTED. Cases
 * run sequentially: ordinary test failures do not suppress later cases, while fork crashes can abort the JVM. Use the
 * per-isolation filter below with a fresh JVM for each level to complete a failure-tolerant campaign.
 *
 * <p>
 * Run the full campaign with:
 * </p>
 *
 * <pre>
 * python3 .codex/skills/mvnf/scripts/mvnf.py --it LmdbLargeTransactionGrowthIT#twoHundredMillionStatements \
 *   --retain-logs -- -Drdf4j.lmdb.largeTransaction.enabled=true
 * </pre>
 *
 * <p>
 * The diagnostic selector is {@code #diagnosticSingleTransaction}, enabled separately with
 * {@code -Drdf4j.lmdb.largeTransaction.diagnostic=true}. It writes 250,000 statements and requires at least one resize
 * of each backing map; it is not evidence for the 200-million-row campaign, which requires at least three of each.
 * Select one requested level for a fresh JVM using {@code -Drdf4j.lmdb.largeTransaction.isolation=SNAPSHOT}. Journals
 * are retained in unique directories below {@code work/lmdb-large-transactions}, configurable with
 * {@code rdf4j.lmdb.largeTransaction.artifacts}. Successful test-owned stores are removed by JUnit unless
 * {@code rdf4j.lmdb.largeTransaction.keepStore=true}; failed stores are retained and their locations are recorded in
 * the journals. The generator retains one row; the exhaustive oracle uses one bit per expected row (25 MB for the full
 * case), rather than retaining decoded statements.
 * </p>
 */
@Execution(ExecutionMode.SAME_THREAD)
class LmdbLargeTransactionGrowthIT {

	private static final int LARGE_STATEMENT_COUNT = 200_000_000;
	private static final int DIAGNOSTIC_STATEMENT_COUNT = 250_000;
	private static final int PROGRESS_INTERVAL = 1_000_000;
	private static final long INITIAL_MAP_BYTES = 1024L * 1024L;
	private static final String SUBJECT_PREFIX = "urn:lmdb:large-transaction:subject:";
	private static final String VALUE_PREFIX = "dictionary-value-for-large-transaction-";
	private static final String VALUE_SUFFIX = "-payload";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI[] PREDICATES = {
			VF.createIRI("urn:lmdb:large-transaction:predicate:0"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:1"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:2"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:3")
	};
	private static final Resource[][] CONTEXTS = createContexts();

	static Stream<IsolationLevels> isolationLevels() {
		String requested = System.getProperty("rdf4j.lmdb.largeTransaction.isolation");
		return requested == null ? Arrays.stream(IsolationLevels.values())
				: Stream.of(IsolationLevels.valueOf(requested));
	}

	@ParameterizedTest(name = "200,000,000 statements; requested isolation={0}")
	@MethodSource("isolationLevels")
	@EnabledIfSystemProperty(named = "rdf4j.lmdb.largeTransaction.enabled", matches = "true")
	void twoHundredMillionStatements(IsolationLevels isolation,
			@TempDir(cleanup = CleanupMode.ON_SUCCESS) Path dataDirectory) throws Exception {
		runSingleTransaction(isolation, dataDirectory, LARGE_STATEMENT_COUNT, 3);
	}

	@ParameterizedTest(name = "diagnostic 250,000 statements; requested isolation={0}")
	@MethodSource("isolationLevels")
	@EnabledIfSystemProperty(named = "rdf4j.lmdb.largeTransaction.diagnostic", matches = "true")
	void diagnosticSingleTransaction(IsolationLevels isolation,
			@TempDir(cleanup = CleanupMode.ON_SUCCESS) Path dataDirectory) throws Exception {
		runSingleTransaction(isolation, dataDirectory, DIAGNOSTIC_STATEMENT_COUNT, 1);
	}

	private static void runSingleTransaction(IsolationLevels isolation, Path dataDirectory, int statementCount,
			int minimumMapResizes) throws Exception {
		Path artifactRoot = Path.of(System.getProperty("rdf4j.lmdb.largeTransaction.artifacts",
				"work/lmdb-large-transactions")).toAbsolutePath();
		Files.createDirectories(artifactRoot);
		Path artifacts = Files.createTempDirectory(artifactRoot, statementCount + "-" + isolation + "-");
		Path storeDirectory = Boolean.getBoolean("rdf4j.lmdb.largeTransaction.keepStore")
				? artifacts.resolve("store")
				: dataDirectory.resolve("store");
		Progress progress = new Progress();
		try (Journal journal = new Journal(artifacts.resolve("journal.log"))) {
			journal.line("start requested=" + isolation + " expectedStatements=" + statementCount
					+ " minimumResizesPerMap=" + minimumMapResizes + " initialMapBytes=" + INITIAL_MAP_BYTES
					+ " maxHeapBytes=" + Runtime.getRuntime().maxMemory() + " store=" + storeDirectory
					+ " journal=" + artifacts.resolve("journal.log"));
			LmdbStore store = newStore(storeDirectory);
			SailRepository repository = new SailRepository(store);
			try (RepositoryLifetime ignored = new RepositoryLifetime(repository, journal)) {
				repository.init();
				MapGrowthMetrics.Snapshot before = store.getBackingStore().growthMetricsSnapshot();
				journal.checkpoint("before-transaction", progress, before);
				assertEquals(0L, Values.packLiteral(VF.createLiteral(valueLabel(0))),
						"the generated string values must use the dictionary, with literal inlining left enabled");
				assertEquals(0L, Values.packLiteral(VF.createLiteral(valueLabel(statementCount - 1))));

				try (RepositoryConnection connection = repository.getConnection()) {
					assertFalse(connection.isActive());
					IsolationLevels effective = isolation == IsolationLevels.READ_UNCOMMITTED
							? IsolationLevels.READ_COMMITTED
							: isolation;
					IsolationLevel supported = IsolationLevels.getCompatibleIsolationLevel(isolation,
							store.getSupportedIsolationLevels());
					assertEquals(effective, supported);
					progress.stage = "begin";
					connection.begin(isolation);
					assertTrue(connection.isActive());
					// The repository getter is a next-transaction setting, rather than the Sail's resolved level.
					journal.line("transaction requested=" + isolation + " resolvedSupportedIsolation=" + effective);
					progress.stage = "load";
					for (int index = 0; index < statementCount; index++) {
						progress.generated++;
						connection.add(VF.createIRI(SUBJECT_PREFIX + index), PREDICATES[index % PREDICATES.length],
								VF.createLiteral(valueLabel(index)), CONTEXTS[index % CONTEXTS.length]);
						progress.accepted++;
						if (progress.accepted % PROGRESS_INTERVAL == 0) {
							journal.checkpoint("load", progress, store.getBackingStore().growthMetricsSnapshot());
						}
					}
					assertEquals(statementCount, progress.accepted);
					assertTrue(connection.isActive(), "the entire load must remain in its original transaction");
					MapGrowthMetrics.Snapshot beforeCommit = store.getBackingStore().growthMetricsSnapshot();
					journal.checkpoint("before-commit", progress, beforeCommit);
					progress.stage = "commit";
					connection.commit();
					assertFalse(connection.isActive());
					MapGrowthMetrics.Snapshot afterCommit = store.getBackingStore().growthMetricsSnapshot();
					journal.checkpoint("after-commit", progress, afterCommit);
					journal.line("commit-resizes triple="
							+ (afterCommit.tripleStoreResizes() - beforeCommit.tripleStoreResizes()) + " value="
							+ (afterCommit.valueStoreResizes() - beforeCommit.valueStoreResizes()));
					assertGrowth(before, afterCommit, minimumMapResizes);
				}
				progress.stage = "validate-committed";
				assertCompleteContents(repository, statementCount, progress, journal, store);
			} catch (Exception | Error failure) {
				journal.failure(failure, progress, store);
				throw failure;
			}

			LmdbStore reopenedStore = newStore(storeDirectory);
			SailRepository reopened = new SailRepository(reopenedStore);
			try (RepositoryLifetime ignored = new RepositoryLifetime(reopened, journal)) {
				progress.stage = "reopen";
				reopened.init();
				progress.stage = "validate-reopened";
				assertCompleteContents(reopened, statementCount, progress, journal, reopenedStore);
				journal.line("success requested=" + isolation + " committedStatements=" + statementCount
						+ " persistedStatements=" + statementCount);
			} catch (Exception | Error failure) {
				journal.failure(failure, progress, reopenedStore);
				throw failure;
			}
		}
	}

	private static LmdbStore newStore(Path dataDirectory) {
		return new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig()
				.setTripleDBSize(INITIAL_MAP_BYTES)
				.setValueDBSize(INITIAL_MAP_BYTES));
	}

	private static void assertGrowth(MapGrowthMetrics.Snapshot before, MapGrowthMetrics.Snapshot after,
			int minimumMapResizes) {
		long tripleResizes = after.tripleStoreResizes() - before.tripleStoreResizes();
		long valueResizes = after.valueStoreResizes() - before.valueStoreResizes();
		assertTrue(tripleResizes >= minimumMapResizes,
				"actual backing TripleStore resizes including commit: " + tripleResizes + "; required: "
						+ minimumMapResizes);
		assertTrue(valueResizes >= minimumMapResizes,
				"actual backing ValueStore resizes including commit: " + valueResizes + "; required: "
						+ minimumMapResizes);
	}

	/** One public traversal proves cardinality, the complete generated range, and every row's RDF terms. */
	private static void assertCompleteContents(SailRepository repository, int statementCount, Progress progress,
			Journal journal, LmdbStore store) throws IOException {
		BitSet seen = new BitSet(statementCount);
		progress.validated = 0;
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				String subject = statement.getSubject().stringValue();
				if (!statement.getSubject().isIRI() || !subject.startsWith(SUBJECT_PREFIX)) {
					throw new AssertionError("unexpected subject: " + subject);
				}
				int index = Integer.parseInt(subject, SUBJECT_PREFIX.length(), subject.length(), 10);
				if (index < 0 || index >= statementCount) {
					throw new AssertionError("subject outside generated range: " + subject);
				}
				assertEquals(SUBJECT_PREFIX + index, subject);
				if (seen.get(index)) {
					throw new AssertionError("duplicate subject in public iteration: " + subject);
				}
				seen.set(index);
				assertEquals(PREDICATES[index % PREDICATES.length], statement.getPredicate());
				if (!(statement.getObject() instanceof Literal)) {
					throw new AssertionError("unexpected object for subject: " + subject);
				}
				Literal literal = (Literal) statement.getObject();
				assertEquals(valueLabel(index), literal.getLabel());
				assertEquals(XSD.STRING, literal.getDatatype());
				assertFalse(literal.getLanguage().isPresent());
				assertEquals(CONTEXTS[index % CONTEXTS.length][0], statement.getContext());
				progress.validated++;
				if (progress.validated % PROGRESS_INTERVAL == 0) {
					journal.checkpoint(progress.stage, progress, store.getBackingStore().growthMetricsSnapshot());
				}
			}
		}
		assertEquals(statementCount, progress.validated, "public committed cardinality");
		assertEquals(statementCount, seen.cardinality(), "distinct generated subjects");
		assertEquals(statementCount, seen.nextClearBit(0), "the entire expected subject range must be present");
		journal.checkpoint(progress.stage + "-complete", progress, store.getBackingStore().growthMetricsSnapshot());
	}

	private static String valueLabel(int index) {
		return VALUE_PREFIX + index + VALUE_SUFFIX;
	}

	private static Resource[][] createContexts() {
		Resource[][] contexts = new Resource[8][1];
		for (int index = 1; index < contexts.length; index++) {
			contexts[index][0] = VF.createIRI("urn:lmdb:large-transaction:context:" + index);
		}
		return contexts;
	}

	private static final class Progress {
		private String stage = "initialize";
		private int generated;
		private int accepted;
		private int validated;
	}

	/** Preserve an earlier load failure if shutdown also fails, using ordinary try-with-resources suppression. */
	private static final class RepositoryLifetime implements AutoCloseable {
		private final SailRepository repository;
		private final Journal journal;

		private RepositoryLifetime(SailRepository repository, Journal journal) {
			this.repository = repository;
			this.journal = journal;
		}

		@Override
		public void close() throws IOException {
			repository.shutDown();
			journal.line("shutdown-complete");
		}
	}

	private static final class Journal implements AutoCloseable {
		private final BufferedWriter writer;

		private Journal(Path path) throws IOException {
			writer = Files.newBufferedWriter(path, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
		}

		private void line(String message) throws IOException {
			String line = Instant.now() + " " + message;
			writer.write(line);
			writer.newLine();
			writer.flush();
			System.out.println(line);
		}

		private void checkpoint(String stage, Progress progress, MapGrowthMetrics.Snapshot metrics) throws IOException {
			line("stage=" + stage + " generated=" + progress.generated + " accepted=" + progress.accepted
					+ " validated=" + progress.validated + " tripleResizes=" + metrics.tripleStoreResizes()
					+ " valueResizes=" + metrics.valueStoreResizes() + " growthEpisodes=" + metrics.growthEpisodes()
					+ " fallbackResizes=" + metrics.fallbackResizes() + " growthPhase=" + metrics.currentPhase());
		}

		private void failure(Throwable failure, Progress progress, LmdbStore store) {
			try {
				String type = failure.getClass().getName();
				line("failure stage=" + progress.stage + " generated=" + progress.generated + " accepted="
						+ progress.accepted + " validated=" + progress.validated + " type=" + type
						+ " message=" + failure.getMessage());
				if (store.getBackingStore() != null) {
					checkpoint("failed-" + progress.stage, progress, store.getBackingStore().growthMetricsSnapshot());
				}
			} catch (Exception | Error reportingFailure) {
				// Reporting must preserve both failures, with the transaction/validation failure primary.
				failure.addSuppressed(reportingFailure);
			}
		}

		@Override
		public void close() throws IOException {
			writer.close();
		}
	}
}
